mapper.select:
SELECT COUNT(1) AS totalApplyCount, SUM(CASE WHEN a.status = #{status} THEN 1 ELSE 0 END) AS passedCount, SUM(CASE WHEN a.status != #{status} THEN 1 ELSE 0 END) AS pendingAuditCount FROM `access_apply` AS a LEFT JOIN student_info AS s ON a.student_id = s.id WHERE a.deleted = 0
AND a.apply_time BETWEEN #{startTime} AND #{endTime}
AND s.class_name = #{className}

SELECT DATE_FORMAT(apply_time,'%Y-%m-%d') AS applyTime, COUNT(1) AS totalApplyCount FROM `access_apply` AS a LEFT JOIN student_info AS s ON a.student_id = s.id WHERE a.deleted = 0
AND a.apply_time BETWEEN #{startTime} AND #{endTime}
AND s.class_name = #{className}
GROUP BY applyTime

SELECT a.apply_type AS type, COUNT(1) AS totalApplyCount FROM `access_apply` AS a LEFT JOIN student_info AS s ON a.student_id = s.id WHERE a.deleted = 0
AND a.apply_time BETWEEN #{startTime} AND #{endTime}
AND s.class_name = #{className}
GROUP BY type

SELECT s.class_name AS className, COUNT(1) AS totalCount, SUM(CASE WHEN a.apply_type = #{applyType} THEN 1 ELSE 0 END) AS emergencyCount, SUM(CASE WHEN a.apply_type != #{applyType} THEN 1 ELSE 0 END) AS otherCount FROM `access_apply` AS a LEFT JOIN student_info AS s ON a.student_id = s.id WHERE a.deleted = 0
AND a.apply_time BETWEEN #{startTime} AND #{endTime}
GROUP BY s.class_name
